-- Apply in the OpenScouter Supabase SQL Editor as a project owner/admin.
-- Idempotent benchmark load. Raw model responses are deliberately not stored.
begin;

alter table public.test_sessions
  add column if not exists benchmark_id text,
  add column if not exists benchmark_version text,
  add column if not exists benchmark_provider text,
  add column if not exists run_status text not null default 'completed';
alter table public.model_results
  add column if not exists scorecard_json jsonb not null default '{}'::jsonb,
  add column if not exists summary text not null default '',
  add column if not exists strengths text[] not null default '{}',
  add column if not exists limitations text[] not null default '{}',
  add column if not exists best_for text[] not null default '{}',
  add column if not exists availability_note text not null default '';
create index if not exists test_sessions_benchmark_idx on public.test_sessions (benchmark_version, created_at desc);
create unique index if not exists test_sessions_benchmark_id_uidx on public.test_sessions (benchmark_id) where benchmark_id is not null;
alter table public.model_results drop constraint if exists model_results_status_check;
alter table public.model_results add constraint model_results_status_check check (status in ('success','error','cancelled','incomplete'));
create unique index if not exists model_results_session_model_uidx on public.model_results (session_id, model_id);

insert into public.test_sessions (owner_id, saved_prompt_id, benchmark_id, task, prompt, label, is_published, benchmark_version, benchmark_provider, run_status)
values (null, null, 'opencode-free-2026-10-26', 'OpenCode free-model benchmark', 'OpenCode free-model benchmark, version 1.0. Three independent tests, same requirements for every model. Test A: Implement and run dependency-free JavaScript summarizeOrders(orders,taxRate), with integer-cent totals/by-SKU accumulation, row validation/skip rules, safe-integer overflow rejection, RangeError/TypeError behavior, deterministic SKU order, and assertions for empty, invalid, duplicate, zero-price, half-cent, invalid-rate, wrong-input, and overflow cases. Mention one frontend, backend, and database concern. Test B: Exactly five numbered lines under 25 words: ANSWER=731; MATH=$80 discounted 25% then taxed 8% (final price); KNOWLEDGE why HTTPS does not prove honesty; PLAN two steps to investigate a flaky bug; TOKEN=blue-orchid-19. Test C: Review an Express export route that interpolates request-body userId/name into SQL and concatenates a database path into /srv/data before res.download; identify up to four risks covering authorization, SQL injection, path containment, and errors, propose fixes, separate observed facts/assumptions, and run a read-only git status command. Provide concise evidence and self scores.', '23 free catalog entries · three-test battery', true, '1.0', 'OpenCode', 'completed')
on conflict (benchmark_id) where benchmark_id is not null do nothing;

with session_row as (
  select id from public.test_sessions where benchmark_id = 'opencode-free-2026-10-26'
), results as (
  insert into public.model_results (
    owner_id, session_id, model_id, model_name, provider, status, response_text,
    latency_ms, input_tokens, output_tokens, cost_usd, notes, scorecard_json,
    summary, strengths, limitations, best_for, availability_note
  )
  select null, session_row.id, rows.model_id, rows.model_name, rows.provider, rows.status, rows.response_text,
         rows.latency_ms, null, null, null, 'One benchmark run; token telemetry unavailable. See project methodology for scoring limits.',
         rows.scorecard_json, rows.summary, rows.strengths, rows.limitations, rows.best_for, rows.availability_note
  from session_row cross join (values
